/* From Uiverse.io by Yaya12085 - Tags: card, dark, editor, code */
.__UIV_SCOPE__ .code-editor {
  max-width: 300px;
  background-color: #1d1e22;
  box-shadow: 0px 4px 30px rgba(0, 0, 0, 0.5);
  border-radius: 8px;
  padding: 2px;
}

.__UIV_SCOPE__ .header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 10px;
}

.__UIV_SCOPE__ .title {
  font-family: Lato, sans-serif;
  font-weight: 900;
  font-size: 14px;
  letter-spacing: 1.57px;
  color: rgb(212 212 212);
}

.__UIV_SCOPE__ .icon {
  width: 20px;
  transition: .2s ease;
}

.__UIV_SCOPE__ .icon:hover {
  cursor: pointer;
  border-radius: 50px;
  background-color: #6e7281;
}

.__UIV_SCOPE__ .editor-content {
  margin: 0 10px 10px;
  color: white;
}

.__UIV_SCOPE__ .property {
  margin-left: 30px;
}

.__UIV_SCOPE__ .property:hover {
  cursor: text;
}

.__UIV_SCOPE__ .editor-content .color-0 {
  color: rgb(86 156 214);
}

.__UIV_SCOPE__ .editor-content .color-1 {
  color: rgb(182 206 168);
}

.__UIV_SCOPE__ .editor-content .color-2 {
  color: rgb(156 220 254);
}

.__UIV_SCOPE__ .editor-content .color-3 {
  color: rgb(207 146 120);
}

.__UIV_SCOPE__ .color-preview-1,.__UIV_SCOPE__ .color-preview-2 {
  height: 8px;
  width: 8px;
  border: 1px solid #fff;
  display: inline-block;
  margin-right: 3px;
}

.__UIV_SCOPE__ .color-preview-1 {
  background-color: #1d1e22;
}

.__UIV_SCOPE__ .color-preview-1 {
  background-color: rgba(0, 0, 0, 0.5);
}
